package app.kaze.data

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

class MvPluginFileTest {

    private val plugins = """
        // Generated by RPG Maker.
        var ${'$'}plugins = [
        {"name":"Bracket","status":true,"description":"uses ] and [ inside","parameters":{}},
        {"name":"Quoted","status":true,"description":"a \"quote\" here","parameters":{}}
        ];
    """.trimIndent()

    private val bridge =
        """{"name":"KazeBridge","status":true,"description":"Kaze runtime bridge","parameters":{}}"""

    @Test
    fun `insert keeps descriptions with brackets intact`() {
        val patched = assertNotNull(MvPluginFile.insert(plugins, bridge))
        assertTrue(patched.contains("\"KazeBridge\""))
        assertTrue(patched.contains("uses ] and [ inside"))
        assertEquals(3, Regex("\"name\":").findAll(patched).count())
        assertTrue(patched.trimEnd().endsWith("];"))
    }

    @Test
    fun `insert is idempotent`() {
        val once = assertNotNull(MvPluginFile.insert(plugins, bridge))
        val twice = assertNotNull(MvPluginFile.insert(once, bridge))
        assertEquals(once, twice)
    }

    @Test
    fun `remove deletes only the bridge entry`() {
        val installed = assertNotNull(MvPluginFile.insert(plugins, bridge))
        val removed = assertNotNull(MvPluginFile.removeEntry(installed, "KazeBridge"))
        assertTrue(!removed.contains("KazeBridge"))
        assertTrue(removed.contains("Bracket"))
        assertTrue(removed.contains("Quoted"))
        assertEquals(2, Regex("\"name\":").findAll(removed).count())
    }

    @Test
    fun `a comment mentioning plugins does not misanchor the edit`() {
        val text = "// legacy \$plugins = [];\nvar \$plugins = [];"
        val patched = assertNotNull(MvPluginFile.insert(text, bridge))
        assertTrue(patched.startsWith("// legacy \$plugins = [];"))
        assertTrue(patched.contains("KazeBridge"))
    }

    @Test
    fun `text outside the array is preserved`() {
        val text = "// header\n${plugins}\n// footer"
        val patched = assertNotNull(MvPluginFile.insert(text, bridge))
        assertTrue(patched.startsWith("// header"))
        assertTrue(patched.trimEnd().endsWith("// footer"))
        assertTrue(patched.contains("uses ] and [ inside"))
    }

    @Test
    fun `a trailing comma does not break the edit`() {
        val text = "var \$plugins = [\n{\"name\":\"Only\",\"status\":true,\"description\":\"\",\"parameters\":{}},\n];"
        val patched = assertNotNull(MvPluginFile.insert(text, bridge))
        assertTrue(patched.contains("KazeBridge"))
        assertTrue(patched.contains("Only"))
    }

    @Test
    fun `malformed file is rejected`() {
        assertNull(MvPluginFile.insert("var \$plugins = [ {", bridge))
        assertNull(MvPluginFile.removeEntry("nothing here", "KazeBridge"))
    }
}
